description:
[
  {
    "topic": "Fed policy path / FOMC speaker commentary",
    "why_gold_cares": "Hawkish repricing lifts real yields and DXY, raising the opportunity cost of holding non-yielding gold",
    "impact_threshold": "Unexpected hawkish shift in rate-cut timing or dot-plot guidance from voting members",
    "directional_risk": "BEARISH_GOLD"
  },
  {
    "topic": "US 10Y real yield (DFII10) and nominal yield momentum",
    "why_gold_cares": "Rising real yields directly increase carry cost of gold; current 2.11% real yield is elevated",
    "impact_threshold": "Material multi-bp daily move or breakout above recent range",
    "directional_risk": "BEARISH_GOLD"
  },
  {
    "topic": "DXY dollar index trajectory",
    "why_gold_cares": "Stronger dollar makes gold more expensive in non-USD terms; DXY pushing toward 100 pressures gold",
    "impact_threshold": "Decisive break of round-number level with follow-through volume",
    "directional_risk": "BEARISH_GOLD"
  },
  {
    "topic": "US inflation prints (PCE/CPI) and scheduled releases",
    "why_gold_cares": "Hot inflation delays cuts and lifts yields; cooler prints revive cut bets and support gold",
    "impact_threshold": "Surprise vs consensus large enough to move Fed-cut odds",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "US labor data (NFP/claims)",
    "why_gold_cares": "Labor strength supports higher-for-longer rates; weakness fuels cut bets and safe-haven flows",
    "impact_threshold": "Significant beat/miss vs expectations",
    "directional_risk": "TWO_WAY"
  },
  {
    "topic": "Geopolitical shocks / safe-haven flows",
    "why_gold_cares": "Acute risk events trigger defensive bid for gold regardless of yield backdrop",
    "impact_threshold": "Sudden escalation, military conflict, or sanctions headline",
    "directional_risk": "BULLISH_GOLD"
  },
  {
    "topic": "Central bank gold demand / reserve diversification",
    "why_gold_cares": "Sustained official-sector buying provides structural demand floor",
    "impact_threshold": "Large reported monthly purchases or policy shift toward gold reserves",
    "directional_risk": "BULLISH_GOLD"
  },
  {
    "topic": "Treasury auction demand / supply dynamics",
    "why_gold_cares": "Weak auctions push yields higher, pressuring gold; strong demand caps yields",
    "impact_threshold": "Notable tail or strong bid-to-cover surprise",
    "directional_risk": "TWO_WAY"
  }
]
